OUT = os.path.join(os.path.expanduser("~"), "TESR_tts")
os.makedirs(OUT, exist_ok=True)
async def one(k, t, v, r, p):
    f = os.path.join(OUT, k + ".mp3")
    if os.path.exists(f) and os.path.getsize(f) > 1000: return
    for i in range(4):
        try:
            await edge_tts.Communicate(t, v, rate=r, pitch=p).save(f); return
        except Exception as e:
            print("retry", k, e); await asyncio.sleep(2)
    raise SystemExit("failed " + k)
async def main():
    for it in ITEMS:
        await one(*it); print("ok", it[0], flush=True)
asyncio.run(main())
dl = os.path.join(os.path.expanduser("~"), "Downloads")
z = os.path.join(dl if os.path.isdir(dl) else os.path.expanduser("~"), "TESR_tts.zip")
with zipfile.ZipFile(z, "w") as zf:
    for it in ITEMS: zf.write(os.path.join(OUT, it[0] + ".mp3"), it[0] + ".mp3")
print("ZIP", z)
